'use strict';
const sections={information:'Unit information',defects:'Visual inspection',tests:'Performance tests',measurements:'Measurements',packing:'Packing & traceability',review:'Review & submit'};
function localKey(id=S.inspection?.id){return `qualis:${S.user.id}:inspection:${id}`;}
function stash(){}
function markDirty(){S.dirty=true;S.generation++;saveMessage('Unsaved changes','clock');}
function saveMessage(text,glyph='cloud-check',error=false){const el=$('#save-state');if(el){el.classList.toggle('error',error);el.innerHTML=icon(glyph)+esc(text);}}
async function flush(){syncActivityState();return true;}
function withTimeout(promise,ms,message){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error(message)),ms);})]).finally(()=>clearTimeout(timer));}
async function evaluateCurrent(force=false){
    if(!S.inspection)return null;
    syncActivityState();
    const id=S.inspection.id,generation=S.generation;
    if(!force&&S.validationGeneration===generation&&S.inspection.evaluation)return S.inspection.evaluation;
    S.validationId=id;
    const evaluation=localEvaluateInspection(S.inspection);
    if(S.inspection?.id!==id||S.generation!==generation)return S.inspection?.evaluation||null;
    S.inspection.evaluation=evaluation;
    S.inspection.result=evaluation.result;
    S.validationGeneration=generation;
    updateProgress();
    return evaluation;
}
function updateProgress(){
    const i=S.inspection;if(!i)return;
    $$('.activity').forEach((el,n)=>{const result=i.evaluation.sections[el.dataset.section];el.classList.toggle('has-fail',result==='fail');const mark=$('.step-mark',el);if(mark){mark.setAttribute('aria-hidden','true');mark.innerHTML=result==='pass'?icon('check'):n+1;}});
    const current=$('#unit-result');if(current)current.innerHTML=status(i.result);
    for(const metric of S.meta.products[i.product].metrics){const c=i.evaluation.checks[metric.key];if(!c)continue;const badge=$('#metric-result-'+metric.key);if(badge)badge.innerHTML=status(c.result);const tab=$(`.measure-tab[data-metric="${metric.key}"]`);if(tab)tab.innerHTML=`<span>${metric.label}</span>${c.result==='fail'?`<span class="attention">${icon('alert-circle')}</span>`:`<small>${c.entered}/${c.expected}</small>`}`;
        if(['length_a','glove_length','gap_length'].includes(metric.key)&&c.result==='fail'&&badge&&!$(`[name="${metric.key}_defect"]`)){
            const block=document.createElement('div');block.style.marginTop='18px';block.innerHTML=select(metric.key+'_defect','Failure reason',metric.key==='gap_length'?['Gap Length out of spec','No Gap Length']:['Short Length','Long Length'],i.data.fields[metric.key+'_defect']);$('#reading-stats-'+metric.key)?.after(block);$('select',block).onchange=ev=>{i.data.fields[metric.key+'_defect']=ev.target.value;markDirty();};
        }
    }
    const head=$('.form-section-head>.status');if(head&&i.evaluation.sections[S.section])head.outerHTML=status(i.evaluation.sections[S.section]);
}
async function inspection(q,ticket){const i=await api('inspection',null,{id:q.get('id')});if(ticket!==S.routeTicket)return;if(!i.editable){location.hash='record?id='+i.id;return;}normalizeInspectionData(i);S.inspection=i;S.validationGeneration=-1;S.validationPromise=null;S.dirty=false;S.conflict=false;S.section=q.get('section')||'information';if(!sections[S.section])S.section='information';S.metric=q.get('metric')||'weight';if(S.section==='review'){try{await evaluateCurrent();}catch{}}renderInspection();}
function normalizeInspectionData(i){i.data??={};if(Array.isArray(i.data.measurements))i.data.measurements={};if(Array.isArray(i.data.tests))i.data.tests={};i.data.measurements??={};i.data.tests??={};i.data.defects??=[];i.data.fields??={};i.data.defect_checks??={};}
function renderInspection(){const i=S.inspection;if(!i)return;$('#main').className='workspace inspection-space';const complete=i.units.filter(u=>u.state!=='draft').length;$('#main').innerHTML=`<div class="page-heading inspection-heading"><div><div class="eyebrow">${productLabel(i.product)} inspection · QI-${String(i.id).padStart(5,'0')}</div><h1>SO ${esc(i.so_number)}</h1><div class="set-context"><strong>${esc(i.glove_type)}</strong><span>Size ${esc(sizeLabel(i))}</span><span class="context-divider"></span><span>${esc(i.common.customer||'Customer not recorded')}</span><span class="context-divider"></span><span id="unit-result">${status(i.result)}</span></div></div><div class="actions">${button(`<span>${esc(i.unit_label)} <small>${complete} of ${i.units.length} units submitted</small></span>`,'units','stack-2','unit-button')}<a class="icon-btn" href="#record?id=${i.id}" title="View record and audit trail" aria-label="View record and audit trail">${icon('file-search')}</a></div></div><nav class="activity-nav" aria-label="Inspection activities">${Object.entries(sections).map(([key,title],n)=>`<button class="activity ${S.section===key?'active':''} ${i.evaluation.sections[key]==='fail'?'has-fail':''}" data-action="section" data-section="${key}" ${S.section===key?'aria-current="step"':''}><span class="step-mark">${i.evaluation.sections[key]==='pass'?icon('check'):n+1}</span>${title}</button>`).join('')}</nav><div id="activity-content"></div>`;$('.actionbar')?.remove();$('.app-body').insertAdjacentHTML('beforeend',`<footer class="actionbar"><div class="save-state" id="save-state">${icon('clock')}Changes stay on this page until Submit</div><div class="actions">${S.section==='review'?(button('Submit inspection','submit','send','primary')+button('Submit & next pallet','submit-next','arrow-right')):button('Continue','continue','arrow-right','primary')}</div></footer>`);bindFixedActivityNav();renderActivity();}
function bindFixedActivityNav(){
    const nav=$('.activity-nav');
    if(!nav)return;
    const active=$('.activity.active',nav);
    if(!active)return;
    // Keep the current step visible when the mobile navigation scrolls sideways.
    if(nav.scrollWidth>nav.clientWidth)nav.scrollLeft=Math.max(0,active.offsetLeft-nav.offsetLeft-7);
}
function renderActivity(){const i=S.inspection;const target=$('#activity-content');if(!target)return;switch(S.section){case'information':target.innerHTML=informationView(i);break;case'defects':target.innerHTML=defectsView(i);break;case'tests':target.innerHTML=testsView(i);break;case'measurements':target.innerHTML=measurementsView(i);break;case'packing':target.innerHTML=packingView(i);break;case'review':target.innerHTML=reviewView(i);break;}if(S.section==='information'){$('.subheading',target).classList.add('section-head');$('.subheading',target).insertAdjacentHTML('beforeend',button('Edit order details','edit-order','edit','small'));}bindActivity();bindTabFlow();}
const activityTabSelector='input:not([type="hidden"]):not([disabled]):not([readonly]),select:not([disabled]),textarea:not([disabled]):not([readonly]),button:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])';
function activityFocusables(root=$('#activity-content')){if(!root)return[];return $$(activityTabSelector,root).filter(el=>el.offsetParent!==null&&!el.hidden&&!el.closest('[hidden]')&&!el.closest('dialog:not([open])'));}
function focusActivityControl(position='first'){const controls=activityFocusables();const target=position==='last'?controls[controls.length-1]:controls[0];if(!target)return;target.focus({preventScroll:true});if(target.select&&['INPUT','TEXTAREA'].includes(target.tagName))target.select();target.scrollIntoView({block:'center',behavior:'smooth'});}
async function tabToAdjacentActivity(backward=false){const list=Object.keys(sections),current=list.indexOf(S.section),next=current+(backward?-1:1);if(next<0||next>=list.length)return false;await sectionChange(list[next]);setTimeout(()=>focusActivityControl(backward?'last':'first'),80);return true;}
function bindTabFlow(){const root=$('#activity-content');if(!root||root.dataset.tabFlowBound)return;root.dataset.tabFlowBound='1';root.addEventListener('keydown',async e=>{if(e.key!=='Tab'||e.altKey||e.ctrlKey||e.metaKey)return;if(e.target.closest('dialog'))return;const controls=activityFocusables(root);if(!controls.length)return;const index=controls.indexOf(e.target);if(index===-1)return;const goingBack=e.shiftKey,atStart=index===0,atEnd=index===controls.length-1;if((goingBack&&!atStart)||(!goingBack&&!atEnd))return;const list=Object.keys(sections),current=list.indexOf(S.section),next=current+(goingBack?-1:1);if(next<0||next>=list.length)return;e.preventDefault();await tabToAdjacentActivity(goingBack);});}
function surface(title,description,body,right=''){return `<section class="form-surface"><header class="form-section-head"><div><h2>${title}</h2><p>${description}</p></div>${right}</header><div class="form-content">${body}</div></section>`;}
function informationView(i){const f=i.data.fields,refs=S.meta.products[i.product].references;return surface('Confirm this inspection unit','Order details are shared. Sampling, batch and unit identity belong to this inspection.',`<div class="subheading"><h3>Order context</h3></div><dl class="key-values" style="grid-template-columns:repeat(3,minmax(0,1fr));margin:0">${Object.entries({Factory:i.common.factory,Plant:i.common.plant,'Item number':i.common.item_no,'Lot number':i.common.lot_no,Customer:i.common.customer,Country:i.common.country,Brand:i.common.brand,'Product type':i.common.product_type,Colour:i.common.colour}).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'Not recorded')}</dd></div>`).join('')}</dl><div class="divider"></div><div class="subheading"><h3>Unit identity & sampling</h3><p>Fields marked * are needed before submission.</p></div><div class="field-grid">${input('batch_no','Batch number *',f.batch_no)}${input('pallet_no','Pallet number *',f.pallet_no)}${input('carton_no','Carton number',f.carton_no)}${select('glove_type_code','Glove Type / Code',refs['Glove Type'],f.glove_type_code||i.glove_type)}${input('inspection_date','Inspection date *',f.inspection_date,'date')}${select('inspection_status','Inspection status *',refs['Inspection Status'],f.inspection_status)}${select('inspector_id','Inspector ID *',refs['Inspector ID'],f.inspector_id)}${refs.Embossment?select('embossment','Embossment',refs.Embossment,f.embossment):input('embossment','Embossment',f.embossment)}${select('machine_no',i.product==='hdpe'?'HD number':'STM number',refs[i.product==='hdpe'?'HD No.':'STM No.'],f.machine_no)}${input('stamping_date','Stamping date',f.stamping_date,'date')}${input('sample_size','Sample size (pcs) *',f.sample_size,'number','min="1" step="1"','Enter the approved sampling quantity.')}${input('sample_qty','Sample quantity (cartons x pcs) *',f.sample_qty,'text','placeholder="e.g. 2 cartons x 100 pcs"')}${input('cartons_per_pallet','Cartons per pallet *',f.cartons_per_pallet,'number','min="0" step="1"')}</div>`,status(i.evaluation.sections.information));}
function defectsView(i){const data=i.data;data.defect_checks??={};data.defects??=[];const masters=S.meta.defects.filter(d=>d.product===i.product);const quantity=id=>Number(data.defects.find(d=>d.defect_id===id)?.quantity||1);const decision=id=>data.defect_checks[id]||(data.defects.some(d=>d.defect_id===id)?'fail':'na');const categories=[...new Set(masters.map(d=>d.category))];const totals=Object.fromEntries(categories.map(c=>[c,data.defects.filter(d=>d.category===c).reduce((n,d)=>n+Number(d.quantity),0)]));const categoryCards=categories.map(c=>{const total=totals[c]||0;return `<div class="category"><div class="category-name">${c==='Major'?'Major visual':c==='Minor'?'Minor visual':c}</div><div class="category-total"><strong>${total}</strong>${status(total>0?'fail':'pass')}</div><small class="muted">${masters.filter(d=>d.category===c).length} checks</small></div>`;}).join('');return surface('Visual inspection','Review every visual defect. Default is N/A; mark FAIL only when a defect is found.',`<div class="category-grid">${categoryCards}</div><div class="section-head"><h3>Defect checklist <span class="tag">${data.defects.length} failed</span></h3><span class="muted" style="font-size:11px">Acceptance: zero defects in every category</span></div><div class="table-wrap"><table class="defect-table defect-check-table"><thead><tr><th>Category</th><th>Defect</th><th>Code</th><th>Decision</th><th>Qty</th></tr></thead><tbody>${masters.map(d=>{const current=decision(d.id),qty=quantity(d.id);return `<tr class="${current==='fail'?'failed':''}"><td>${esc(d.category)}</td><td><strong>${esc(d.name)}</strong></td><td>${esc(d.code||'')}</td><td><div class="segments defect-decision" role="group" aria-label="${esc(d.name)} decision">${['na','pass','fail'].map(v=>`<button type="button" data-action="defect-status" data-defect-id="${esc(d.id)}" data-value="${v}" class="${current===v?'selected '+v:''}" aria-pressed="${current===v}">${v==='na'?'N/A':v.toUpperCase()}</button>`).join('')}</div></td><td><input class="defect-qty" aria-label="${esc(d.name)} quantity" type="number" min="1" max="1000000" step="1" data-defect-qty="${esc(d.id)}" value="${current==='fail'?qty:''}" ${current==='fail'?'':'disabled'}></td></tr>`;}).join('')}</tbody></table></div><div style="margin-top:23px"><label class="field"><span>Visual inspection remarks</span><textarea name="defect_remarks" placeholder="Location, appearance, or other useful observations">${esc(data.fields.defect_remarks)}</textarea></label></div>`,status(i.evaluation.sections.defects));}
function testsView(i){const definition=S.meta.products[i.product];const rows=definition.tests.map(test=>{const values=i.data.tests[test.key]||[];const normalized=Array.from({length:test.samples},(_,n)=>values[n]||'na');const result=normalized.includes('fail')?'fail':normalized.includes('pass')?'pass':'na';return `<div class="test-group"><div><h3>${test.label}</h3><p>${test.samples===1?'Record the observed result':test.samples+' independent samples'}</p></div><div class="test-readings">${Array.from({length:test.samples},(_,n)=>`<div class="test-sample"><small>${test.samples===1?'Result':'Sample '+(n+1)}</small><div class="segments" role="group" aria-label="${test.label} sample ${n+1}">${['na','pass','fail'].map(v=>`<button type="button" data-action="test-value" data-test="${test.key}" data-sample="${n}" data-value="${v}" class="${normalized[n]===v?'selected '+v:''}" aria-pressed="${normalized[n]===v}">${v==='na'?'N/A':v.toUpperCase()}</button>`).join('')}</div></div>`).join('')}</div><div>${status(result)}</div>${result==='fail'?`<div class="test-failure">${test.defects?select(test.key+'_defect','Failure reason',test.defects,i.data.fields[test.key+'_defect']):icon('alert-circle')+' '+esc(test.failure)}</div>`:''}</div>`;}).join('');return surface('Performance tests',i.product==='hdpe'?'Check seal integrity, donning, smell and layering.':'Check air pressure, seal integrity, donning and smell.',`${i.product==='cpetpe'?`<section style="border-bottom:1px solid var(--line);padding-bottom:24px;margin-bottom:24px">${metricTable(i,definition.metrics.find(m=>m.key==='air_pump'))}</section>`:''}${rows}`,status(i.evaluation.sections.tests));}
function readingResult(value,limit){if(limit.record_only)return 'na';if(value===null||value===undefined||value==='')return'pending';if(limit.na)return'na';if(limit.min===null||limit.min===undefined){if(limit.max===null||limit.max===undefined)return'unassessed';}return ((limit.min!==null&&limit.min!==undefined&&Number(value)<Number(limit.min)-1e-7)||(limit.max!==null&&limit.max!==undefined&&Number(value)>Number(limit.max)+1e-7))?'fail':'pass';}
function rangeText(l,unit=''){if(l.na)return'Not applicable';if(l.min==null&&l.max==null)return'No specification';return `${l.min??'No minimum'} to ${l.max??'no maximum'}${unit?' '+unit:''}`;}
function reasonText(value,limit,result){if(result==='pending')return'Awaiting reading';if(result==='na')return'Not applicable';if(result==='unassessed')return'No approved limit';if(result==='pass')return'Within specification';if(limit.min!=null&&Number(value)<limit.min)return `${Number((limit.min-Number(value)).toFixed(6))} below minimum ${limit.min}`;return `${Number((Number(value)-limit.max).toFixed(6))} above maximum ${limit.max}`;}
function localAggregate(results){for(const state of ['fail','pending','hold','unassessed'])if(results.includes(state))return state;return results.some(r=>r!=='na')?'pass':'na';}
function localSpecRange(limit,unit=''){if((limit.min??null)===null&&(limit.max??null)===null)return'No specification';return `${limit.min??'no minimum'} to ${limit.max??'no maximum'}${unit?' '+unit:''}`;}
function localEvaluateInspection(i){const definition=S.meta.products[i.product],data=i.data,limits=i.spec?.limits||{},checks={},issues=[],missing=[],categories=['Critical','Holes','Major','Minor','Packaging'];
    for(const [key,label] of Object.entries({batch_no:'Batch number',pallet_no:'Pallet number',inspection_date:'Inspection date',inspector_id:'Inspector ID',inspection_status:'Inspection status',sample_size:'Sample size',sample_qty:'Sample quantity',cartons_per_pallet:'Cartons per pallet'}))if(String(data.fields?.[key]??'').trim()==='')missing.push({section:'information',key,message:`Enter ${label}.`});
    for(const metric of definition.metrics){const key=metric.key,limit=limits[key]||{},values=data.measurements?.[key]||[],results=[];if(limit.na){checks[key]={label:metric.label,section:metric.section,result:'na',entered:0,expected:0,readings:[]};continue;}for(let n=0;n<metric.samples;n++){const v=values[n]??null,r=readingResult(v,limit);results.push(r);if(r==='fail')issues.push({section:metric.section,key,sample:n+1,message:`${metric.label} sample ${n+1}: ${v} ${metric.unit}; required ${localSpecRange(limit,metric.unit)}.`});}const entered=values.filter(v=>v!==null&&v!==''&&v!==undefined).length;const assessed=results.filter(r=>r!=='pending');let result=localAggregate(assessed);if(key==='thickness'&&i.product==='hdpe'&&(limit.min??null)===null&&(limit.max??null)===null&&entered>0)result='na';if(key==='air_pump'&&i.product==='cpetpe'&&(limit.min??null)===null&&(limit.max??null)===null&&entered>0)result='pass';if(result==='unassessed'&&entered>0)issues.push({section:metric.section,key,message:`${metric.label}: specification not available; requires review.`});checks[key]={label:metric.label,section:metric.section,result,entered,expected:metric.samples,readings:results};}
    for(const test of definition.tests){const key=test.key,values=data.tests?.[key]||[],results=[];for(let n=0;n<test.samples;n++)results.push(String(values[n]||'na').toLowerCase());const assessed=results.filter(r=>r!=='pending');const result=localAggregate(assessed);checks[key]={label:test.label,section:'tests',result,readings:results};if(result==='fail'){issues.push({section:'tests',key,message:`${test.label}: ${test.failure||data.fields?.[key+'_defect']||'Failed test'}.`});if(test.defects&&!data.fields?.[key+'_defect'])missing.push({section:'tests',key,message:`Select the ${test.label} defect.`});}}
    for(const category of categories){const total=(data.defects||[]).filter(d=>d.category===category).reduce((n,d)=>n+Number(d.quantity||0),0),result=total>0?'fail':'pass';checks['defect_'+category]={label:category,section:'defects',result,total};if(result==='fail')issues.push({section:'defects',key:category,message:`${category}: ${total} defect(s). Zero-tolerance acceptance exceeded.`});}
    for(const [key,label] of Object.entries({pcs:'Pieces',inner:'Inner',polybag:'Polybag'})){const value=data.fields?.['count_'+key]??'',disposition=data.fields?.['count_'+key+'_result']??'',result=disposition===''?'pending':disposition==='PASS'?'pass':'fail';checks['count_'+key]={label:label+' count',section:'packing',result};if(value===''||disposition==='')missing.push({section:'packing',key:'count_'+key,message:`Complete ${label} count and disposition.`});if(result==='fail')issues.push({section:'packing',key:'count_'+key,message:`${label} count: ${disposition}.`});}
    for(const [key,label] of Object.entries({scale_id:'Weighing scale ID',ruler_id:'Ruler ID',gauge_id:'Thickness gauge ID',packer_id:'Packer ID'}))if(!data.fields?.[key])missing.push({section:'packing',key,message:`Enter ${label}.`});
    for(const key of ['length_a','glove_length','gap_length'])if(checks[key]?.result==='fail'&&!data.fields?.[key+'_defect'])missing.push({section:'measurements',key,message:`Select the ${checks[key].label} defect.`});
    const sectionStates={};for(const section of ['information','defects','tests','measurements','packing']){const states=Object.values(checks).filter(c=>c.section===section).map(c=>c.result);if(missing.some(m=>m.section===section))states.push('pending');sectionStates[section]=localAggregate(states.length?states:['pass']);}
    let result=localAggregate(Object.values(sectionStates));if(result==='unassessed')result='hold';return{result,checks,sections:sectionStates,issues,missing,can_submit:missing.length===0,passed:Object.values(checks).filter(c=>c.result==='pass').length,failed:Object.values(checks).filter(c=>c.result==='fail').length};
}
function measurementsView(i){const metrics=S.meta.products[i.product].metrics.filter(m=>m.section==='measurements');if(!metrics.some(m=>m.key===S.metric))S.metric=metrics[0].key;const current=metrics.find(m=>m.key===S.metric);return `<section class="form-surface measure-layout"><nav class="measure-menu" aria-label="Measurement groups"><div class="eyebrow">Measurements</div>${metrics.map(m=>{const c=i.evaluation.checks[m.key];return `<button class="measure-tab ${m.key===S.metric?'active':''}" data-action="metric" data-metric="${m.key}" ${m.key===S.metric?'aria-current="true"':''}><span>${m.label}</span>${c?.result==='fail'?`<span class="attention">${icon('alert-circle')}</span>`:`<small>${c?.entered||0}/${c?.expected??m.samples}</small>`}</button>`;}).join('')}</nav><div class="measure-main">${metricTable(i,current)}<div class="measurement-footer"><div class="muted" style="font-size:11px">${icon('ruler-measure')} ${esc(i.spec?.reference||'No approved specification')}</div>${button('Next measurement','next-metric','arrow-right','small')}</div></div></section>`;}
function metricTable(i,m,readonly=false){const limit=i.spec?.limits?.[m.key]||{};const values=i.data.measurements[m.key]||[];const c=i.evaluation.checks[m.key]||{};const known=limit.min!=null||limit.max!=null;const naThickness=i.product==='hdpe'&&m.key==='thickness'&&!known;
return `<div class="measure-header"><div><h2>${m.label}</h2><p>${m.samples} ${m.samples===1?'reading':'sample readings'}${m.unit?' · '+m.unit:''}</p></div><div id="metric-result-${m.key}">${status(c.result||'pending')}</div></div>${limit.na?'<div class="notice neutral">This measurement is marked NIL for the selected specification. No readings are required.</div>':`${!known?`<div class="notice">${icon('info-circle')}<div><strong>${naThickness?'Thickness limits not supplied':'Specification not available'}</strong>${naThickness?'Record all three readings. This test is not assessed and does not generate a PASS or FAIL.':'Record the readings for review. No limit from a different product or size will be applied.'}</div></div>`:`<div class="spec-strip"><div><small>Minimum${m.unit?' ('+m.unit+')':''}</small><span class="spec-number">${limit.min??'N/A'}</span></div>${limit.nominal!=null?`<div><small>Nominal</small><span class="spec-number">${limit.nominal}</span></div>`:''}<div><small>Maximum</small><span class="spec-number">${limit.max??'No upper limit'}</span></div><span class="spec-source">${esc(i.spec.reference)}<br>${esc(i.glove_type)} · ${esc(sizeLabel(i))}</span></div>`}<table class="reading-table" aria-label="${m.label} samples"><thead><tr><th>Sample</th><th>Reading${m.unit?' ('+m.unit+')':''}</th><th>Result</th><th>Assessment</th></tr></thead><tbody>${Array.from({length:m.samples},(_,n)=>{const v=values[n],r=readingResult(v,limit);return `<tr data-reading-row="${m.key}-${n}" class="${r==='fail'?'failed':''}"><td class="numeric">${String(n+1).padStart(2,'0')}</td><td>${readonly?esc(v??'Not recorded'):`<input aria-label="${m.label} sample ${n+1}" type="number" min="0" max="1000000" step="any" inputmode="decimal" data-measurement="${m.key}" data-sample="${n}" value="${v??''}" placeholder="${m.unit||'Reading'}">`}</td><td class="sample-status">${status(r)}</td><td class="reason">${esc(reasonText(v,limit,r))}</td></tr>`;}).join('')}</tbody></table><div id="reading-stats-${m.key}" class="reading-stats">${readingStats(values)}</div>${['length_a','glove_length','gap_length'].includes(m.key)&&values.some(v=>readingResult(v,limit)==='fail')?`<div style="margin-top:18px">${select(m.key+'_defect','Failure reason',m.key==='gap_length'?['Gap Length out of spec','No Gap Length']:['Short Length','Long Length'],i.data.fields[m.key+'_defect'],readonly?'disabled':'')}</div>`:''}`}`;}
function readingStats(values){const nums=values.filter(v=>v!==null&&v!==''&&v!==undefined).map(Number);return `<span>Entered<strong>${nums.length}</strong></span><span>Minimum<strong>${nums.length?Math.min(...nums):'--'}</strong></span><span>Average<strong>${nums.length?Number((nums.reduce((a,b)=>a+b,0)/nums.length).toFixed(4)):'--'}</strong></span><span>Maximum<strong>${nums.length?Math.max(...nums):'--'}</strong></span>`;}
function orderDialog(){const i=S.inspection;const f=modal('Edit shared order details',`<p>These details apply to all ${i.units.length} units in this set. Once any unit is submitted, reopen all units before correcting shared order data.</p><div class="field-grid two">${Object.entries({factory:'Factory / plant',item_no:'Item number',lot_no:'Lot number',customer:'Customer',country:'Country',colour:'Colour',brand:'Brand',product_type:'Product type'}).map(([k,l])=>input(k,l,i.common[k])).join('')}</div>`,`<button type="button" class="btn" data-action="close-dialog">Cancel</button><button type="submit" class="btn primary">Save shared details</button>`);f.onsubmit=async e=>{e.preventDefault();try{await api('order',{set_id:i.set_id,token:i.common_token,...formValues(f)});closeModal();S.inspection=await api('inspection',null,{id:i.id});renderInspection();toast('Shared order details updated.');}catch(err){modalError(err);}};}
function packingView(i){const f=i.data.fields;const equipment=S.meta.equipment?.[i.product]||{};const withCurrent=(items=[],value='')=>value&&!items.includes(value)?[value,...items]:items;const equipmentField=(name,label,items)=>{const values=withCurrent(items||[],f[name]||'');return values.length?select(name,label,values,f[name]):input(name,label,f[name]);};const packers=S.meta.packers||[];const packerValues=f.packer_id&&!packers.some(p=>String(p.value)===String(f.packer_id))?[{value:f.packer_id,label:f.packer_id},...packers]:packers;const packerField=input('packer_id','Packer ID *',f.packer_id);return surface('Packing & traceability','Record packaging counts and the instruments used for this inspection.',`<div class="subheading"><h3>Counting</h3><p>Disposition is an inspector selection in the source template.</p></div><div class="table-wrap"><table><thead><tr><th>Packaging level</th><th>Actual count</th><th>Disposition</th><th>Result</th></tr></thead><tbody>${[['pcs','Pieces'],['inner','Inner'],['polybag','Polybag']].map(([k,l])=>`<tr><td>${l}</td><td>${input('count_'+k,l+' count',f['count_'+k],'number','min="0" step="1"')}</td><td>${select('count_'+k+'_result',l+' disposition',['PASS','Less Count','Extra Count'],f['count_'+k+'_result'])}</td><td>${status(!f['count_'+k+'_result']?'pending':f['count_'+k+'_result']==='PASS'?'pass':'fail')}</td></tr>`).join('')}</tbody></table></div><div class="divider"></div><div class="subheading"><h3>Traceability</h3></div><div class="field-grid two">${equipmentField('scale_id','Weighing scale ID *',equipment.scale)}${equipmentField('ruler_id','Ruler ID *',equipment.ruler)}${equipmentField('gauge_id','Thickness gauge ID *',equipment.gauge)}${packerField}<label class="field span-all"><span>Inspection remarks</span><textarea name="remarks">${esc(f.remarks)}</textarea></label></div>`,status(i.evaluation.sections.packing));}
function reviewView(i){const e=i.evaluation;return surface('Review inspection','Resolve incomplete entries and inspect exceptions before submission.',`<div class="review-summary">${icon(e.result==='fail'?'clipboard-x':e.can_submit?'clipboard-check':'clipboard-list')}<div><h2>${e.can_submit?'Ready for supervisor review':e.missing.length+' items need completion'}</h2><p>${esc(i.unit_label)} · ${esc(i.glove_type)} · Size ${esc(sizeLabel(i))}</p></div>${status(e.result)}</div><div class="review-columns"><div><h3>Activity results</h3>${Object.entries(e.sections).map(([k,v])=>`<div class="review-row"><button class="btn ghost small" data-action="section" data-section="${k}">${sections[k]} ${icon('arrow-up-right')}</button>${status(v)}</div>`).join('')}<div class="info-band">${icon('user-check')}<span>Submission locks this record. Verification is completed by a different supervisor.</span></div></div><div><h3>${e.issues.length?'Exceptions ('+e.issues.length+')':'No failed checks'}</h3>${e.issues.map(issue=>issueLink(issue,true)).join('')}${e.missing.length?`<h3 style="margin-top:22px">To complete</h3>${e.missing.map(issue=>issueLink(issue)).join('')}`:'<p class="muted" style="margin-top:12px;font-size:12px">All required readings and traceability fields are recorded.</p>'}</div></div>`,status(e.result));}
function issueLink(issue,failure=false){return `<button class="issue-link ${failure?'failure':''}" data-action="issue" data-section="${issue.section}" data-key="${esc(issue.key)}" data-sample="${issue.sample||''}">${icon(failure?'alert-circle':'circle-dashed')}<span>${esc(issue.message)}</span>${icon('chevron-right')}</button>`;}
function syncActivityState(){const i=S.inspection;if(!i)return;if(Array.isArray(i.data.measurements))i.data.measurements={};if(Array.isArray(i.data.tests))i.data.tests={};$$('#activity-content [data-measurement]').forEach(el=>{const key=el.dataset.measurement,n=Number(el.dataset.sample);i.data.measurements??={};i.data.measurements[key]??=[];i.data.measurements[key][n]=el.value===''?null:Number(el.value);});$$('#activity-content input[name],#activity-content select[name],#activity-content textarea[name]').forEach(el=>{if(el.name&&!el.name.startsWith('defect-')){i.data.fields[el.name]=el.value;}});$$('#activity-content [data-defect-qty]').forEach(el=>{const entry=i.data.defects?.find(d=>d.defect_id===el.dataset.defectQty);if(entry&&el.value!=='')entry.quantity=Math.max(1,Math.min(1000000,Number(el.value||1)));});}
function bindActivity(){const i=S.inspection;if(!i)return;const active=()=>S.inspection?.id===i.id;$$('#activity-content input[name],#activity-content select[name],#activity-content textarea[name]').forEach(el=>{if(el.name.startsWith('defect-'))return;el.addEventListener('input',()=>{if(!active())return;i.data.fields[el.name]=el.value;markDirty();});if(el.tagName==='SELECT')el.addEventListener('change',()=>{if(!active())return;i.data.fields[el.name]=el.value;markDirty();if(S.section==='packing')renderActivity();});});$$('[data-defect-qty]').forEach(el=>{el.addEventListener('input',()=>{if(!active())return;const id=el.dataset.defectQty,entry=i.data.defects.find(d=>d.defect_id===id);if(entry){const qty=Math.max(1,Math.min(1000000,Number(el.value||1)));entry.quantity=Number.isFinite(qty)?qty:1;markDirty();}});el.addEventListener('change',()=>{if(active()&&!el.classList.contains('defect-qty-only'))renderActivity();});});$$('[data-measurement]').forEach(el=>{el.addEventListener('input',()=>{if(!active())return;const key=el.dataset.measurement,n=Number(el.dataset.sample),limit=i.spec?.limits?.[key]||{};const value=el.value===''?null:Number(el.value);i.data.measurements[key]??=[];i.data.measurements[key][n]=value;const r=readingResult(value,limit),cell=el.closest('[data-reading-cell]')||el.closest('tr'),row=el.closest('tr');cell?.classList.toggle('failed',r==='fail');row?.classList.toggle('failed',!!$('.measurement-cell.failed',row));const sampleStatus=$('.sample-status',cell||row),reason=$('.reason',cell||row);if(sampleStatus)sampleStatus.innerHTML=status(r);if(reason)reason.textContent=reasonText(value,limit,r);const stats=$('#reading-stats-'+key);if(stats)stats.innerHTML=readingStats(i.data.measurements[key]);markDirty();});el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const list=$$('[data-measurement]');const next=list[list.indexOf(el)+(e.shiftKey?-1:1)];next?.focus();next?.select();}});});}
function populateDefectOptions(){const category=$('[name=defect-category]').value;$('#defect-options').innerHTML=S.meta.defects.filter(d=>d.product===S.inspection.product&&d.category===category).map(d=>`<option value="${esc(d.code+' - '+d.name)}"></option>`).join('');}
async function sectionChange(section,key='',sample=''){syncActivityState();S.section=section;if(section==='measurements'&&S.meta.products[S.inspection.product].metrics.some(m=>m.key===key))S.metric=key;if(section==='review'){try{await evaluateCurrent();saveMessage('Review checks ready','cloud-check');}catch(err){toast(err.message,true);saveMessage('Review check failed','alert-circle',true);}renderInspection();window.scrollTo({top:0,behavior:'smooth'});return;}renderInspection();if(key){setTimeout(()=>{const el=sample?$(`[data-measurement="${key}"][data-sample="${Number(sample)-1}"]`):$(`[name="${key}"]`);el?.focus();el?.scrollIntoView({block:'center',behavior:'smooth'});},30);}else window.scrollTo({top:0,behavior:'smooth'});}
async function unitSwitcher(){syncActivityState();const i=S.inspection;modal('Inspection units',`<div class="section-head"><span>SO ${esc(i.so_number)} · ${productLabel(i.product)}</span><span class="tag">${i.units.length} units</span></div><label class="search" style="display:block;max-width:none">${icon('search')}<input type="search" id="unit-search" placeholder="Find by pallet, size or SO item" aria-label="Search inspection units"></label><div class="unit-list">${i.units.map(u=>{const meta=`Size ${sizeLabel(u)||'-'} · SO item ${u.so_item_no||'-'}${u.inspection_no?` · Inspection ${u.inspection_no}`:''}`;return `<button type="button" class="unit-option ${u.id===i.id?'current':''}" data-action="open-unit" data-id="${u.id}" data-state="${u.state}" data-label="${esc((u.unit_label+' '+meta+' '+labels[u.state]).toLowerCase())}"><span><strong>${esc(u.unit_label)}</strong><small>${esc(meta)}</small><small>${labels[u.state]}</small></span>${status(u.result)}</button>`;}).join('')}</div>`);$('#dialog').classList.add('unit-switcher-dialog');$('#unit-search').oninput=e=>$$('.unit-option').forEach(el=>el.hidden=!el.dataset.label.includes(e.target.value.toLowerCase()));}
function recoveryDownload(){const data=$('#dialog-form').dataset.recovery;const blob=new Blob([data],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='inspection-'+S.inspection.id+'-recovery.json';a.click();URL.revokeObjectURL(url);}
function measurementLimitSummary(i,m){if(m.key==='thickness')return '';const limit=i.spec?.limits?.[m.key]||{};if(limit.na)return'N/A';if(limit.min==null&&limit.max==null)return'No spec';return `${limit.min??'--'} - ${limit.max??'--'}${m.unit?' '+m.unit:''}`;}
function measurementCell(i,m,n){const limit=i.spec?.limits?.[m.key]||{},values=i.data.measurements[m.key]||[],required=n<m.samples;if(!required)return`<td class="measurement-cell muted-cell">--</td>`;if(limit.na)return`<td class="measurement-cell muted-cell"><span class="status na">${icon('minus')} N/A</span></td>`;const v=values[n],r=readingResult(v,limit);return `<td class="measurement-cell ${r==='fail'?'failed':''}" data-reading-cell="${m.key}-${n}"><input aria-label="${m.label} sample ${n+1}" type="number" min="0" max="1000000" step="any" inputmode="decimal" data-measurement="${m.key}" data-sample="${n}" value="${v??''}" placeholder="${m.unit||'Reading'}"><div class="cell-assessment"><span class="sample-status">${status(r)}</span><small class="reason">${esc(reasonText(v,limit,r))}</small></div></td>`;}
measurementsView=function(i){const metrics=S.meta.products[i.product].metrics.filter(m=>m.section==='measurements');const maxSamples=Math.max(...metrics.map(m=>m.samples));const missing=metrics.filter(m=>{const l=i.spec?.limits?.[m.key]||{};return !l.na&&l.min==null&&l.max==null;});const failing=metrics.filter(m=>(i.evaluation.checks[m.key]?.result)==='fail');return surface('Measurements','Enter readings by sample row. Use Tab or Enter to move across the row, then continue to the next sample.',`<div class="measure-matrix-head"><div>${i.spec?`<span class="tag">${esc(i.spec.reference)}</span><span class="muted">${esc(i.spec.glove_type)} · ${esc(i.spec.size)}</span>`:`<div class="notice">${icon('info-circle')}<div><strong>Specification not available</strong>Masterlist lookup did not find an approved limit for this order context.</div></div>`}</div><div>${failing.length?status('fail'):missing.length?status('hold'):status(i.evaluation.sections.measurements)}</div></div>${missing.length&&i.spec?`<div class="notice">${icon('info-circle')}<div><strong>Some measurement limits are not available</strong>${esc(missing.map(m=>m.label).join(', '))} will be recorded for review.</div></div>`:''}<div class="measurement-grid-wrap"><table class="measurement-grid" aria-label="Measurement readings by sample"><thead><tr><th class="sticky-sample">Sample</th>${metrics.map(m=>`<th><span>${esc(m.label)}</span><small>${esc(measurementLimitSummary(i,m))}</small></th>`).join('')}</tr></thead><tbody>${Array.from({length:maxSamples},(_,n)=>`<tr><th class="sticky-sample numeric">${String(n+1).padStart(2,'0')}</th>${metrics.map(m=>measurementCell(i,m,n)).join('')}</tr>`).join('')}</tbody></table></div><div class="measurement-stats-grid">${metrics.map(m=>`<div><strong>${esc(m.label)}</strong><div id="reading-stats-${m.key}" class="reading-stats compact">${readingStats(i.data.measurements[m.key]||[])}</div></div>`).join('')}</div>`,status(i.evaluation.sections.measurements));}

function matchingSpecifications(i){return (S.meta.specifications||[]).filter(s=>s.product===i.product&&s.size===i.size&&(String(s.glove_type).toLowerCase()===String(i.glove_type).toLowerCase()||String(s.glove_type).toLowerCase()===String(i.data.fields.glove_type_code||'').toLowerCase()));}
async function bindSpecSelector(i){const el=$('[name=spec_id]');if(!el||el.dataset.bound)return;el.dataset.bound='1';el.onchange=async()=>{i.data.fields.spec_id=el.value;markDirty();if(el.value){try{i.spec=await api('spec',null,{id:el.value});}catch(err){toast(err.message,true);}}await evaluateCurrent(true);renderActivity();};}
informationView=function(i){const f=i.data.fields,refs=S.meta.products[i.product].references;return surface('Confirm this inspection unit','Order details are shared. Sampling, batch and unit identity belong to this inspection.',`<div class="subheading"><h3>Order context</h3></div><dl class="key-values" style="grid-template-columns:repeat(3,minmax(0,1fr));margin:0">${Object.entries({Factory:i.common.factory,Plant:i.common.plant,'Item number':i.common.item_no,'Lot number':i.common.lot_no,Customer:i.common.customer,Country:i.common.country,Brand:i.common.brand,'Product type':i.common.product_type,Colour:i.common.colour}).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'Not recorded')}</dd></div>`).join('')}</dl><div class="divider"></div><div class="subheading"><h3>Unit identity & sampling</h3><p>Fields marked * are needed before submission.</p></div><div class="field-grid">${input('batch_no','Batch number *',f.batch_no)}${input('pallet_no','Pallet number *',f.pallet_no)}${input('carton_no','Carton number',f.carton_no)}${select('glove_type_code','Glove Type / Code',refs['Glove Type'],f.glove_type_code||i.glove_type)}${input('inspection_date','Inspection date *',f.inspection_date,'date')}${select('inspection_status','Inspection status *',refs['Inspection Status'],f.inspection_status)}${refs.Embossment?select('embossment','Embossment',refs.Embossment,f.embossment):input('embossment','Embossment',f.embossment)}${select('machine_no',i.product==='hdpe'?'HD number':'STM number',refs[i.product==='hdpe'?'HD No.':'STM No.'],f.machine_no)}${input('stamping_date','Stamping date',f.stamping_date,'date')}${input('sample_size','Sample size (pcs) *',f.sample_size,'number','min="1" step="1"','Enter the approved sampling quantity.')}${input('sample_qty','Sample quantity (cartons x pcs) *',f.sample_qty,'text','placeholder="e.g. 2 cartons x 100 pcs"')}${input('cartons_per_pallet','Cartons per pallet *',f.cartons_per_pallet,'number','min="0" step="1"')}</div>`,status(i.evaluation.sections.information));};
defectsView=function(i){const data=i.data;data.defect_checks??={};data.defects??=[];const masters=S.meta.defects.filter(d=>d.product===i.product);const quantity=id=>Number(data.defects.find(d=>d.defect_id===id)?.quantity||1);const decision=id=>data.defect_checks[id]||(data.defects.some(d=>d.defect_id===id)?'fail':'na');const categories=[...new Set(masters.map(d=>d.category))];const totals=Object.fromEntries(categories.map(c=>[c,data.defects.filter(d=>d.category===c).reduce((n,d)=>n+Number(d.quantity),0)]));const chips=categories.map(c=>`<div class="defect-summary-chip ${totals[c]?'failed':''}"><span>${esc(c==='Major'?'Major visual':c==='Minor'?'Minor visual':c)}</span><strong>${totals[c]||0}</strong>${status((totals[c]||0)>0?'fail':'pass')}</div>`).join('');return surface('Visual inspection','Review every visual defect. Default is N/A; mark FAIL only when a defect is found.',`<div class="defect-summary-row">${chips}</div><div class="section-head compact-defect-head"><h3>Defect checklist <span class="tag">${data.defects.length} failed</span></h3><span class="muted" style="font-size:11px">Acceptance: zero defects in every category</span></div><div class="table-wrap compact-defect-wrap"><table class="defect-table compact-defect-table"><thead><tr><th>State</th><th>Defect</th><th>Decision</th><th>Qty</th></tr></thead><tbody>${masters.map(d=>{const current=decision(d.id),qty=quantity(d.id);return `<tr class="${current==='fail'?'failed':''}"><td><span class="defect-state">${esc(d.category)}</span></td><td><strong class="defect-name">${esc(d.name)}</strong><span class="defect-code">CODE ${esc(d.code||'-')}</span></td><td><div class="segments defect-decision" role="group" aria-label="${esc(d.name)} decision">${['na','pass','fail'].map(v=>`<button type="button" data-action="defect-status" data-defect-id="${esc(d.id)}" data-value="${v}" class="${current===v?'selected '+v:''}" aria-pressed="${current===v}">${v==='na'?'N/A':v.toUpperCase()}</button>`).join('')}</div></td><td><input class="defect-qty" aria-label="${esc(d.name)} quantity" type="number" min="1" max="1000000" step="1" data-defect-qty="${esc(d.id)}" value="${current==='fail'?qty:''}" ${current==='fail'?'':'disabled'}></td></tr>`;}).join('')}</tbody></table></div><div style="margin-top:18px"><label class="field"><span>Visual inspection remarks</span><textarea name="defect_remarks" placeholder="Location, appearance, or other useful observations">${esc(data.fields.defect_remarks)}</textarea></label></div>`,status(i.evaluation.sections.defects));};
measurementsView=function(i){const metrics=S.meta.products[i.product].metrics.filter(m=>m.section==='measurements');const maxSamples=Math.max(...metrics.map(m=>m.samples));const missing=metrics.filter(m=>{const l=i.spec?.limits?.[m.key]||{};return !l.na&&l.min==null&&l.max==null;});const failing=metrics.filter(m=>(i.evaluation.checks[m.key]?.result)==='fail');const specs=matchingSpecifications(i);const specChoices=specs.map(s=>({value:s.id,label:`${s.reference_name} · ${s.revision}`}));const selected=i.data.fields.spec_id||i.spec?.id||'';setTimeout(()=>bindSpecSelector(i),0);return surface('Measurements','Enter readings by sample row. Use Tab or Enter to move across the row, then continue to the next sample.',`<div class="measure-matrix-head spec-select-head"><div>${specChoices.length?select('spec_id','Specification reference',specChoices,selected):`<div class="notice">${icon('info-circle')}<div><strong>Specification not available</strong>Masterlist lookup did not find an approved limit for this order context.</div></div>`}${i.spec?`<span class="muted spec-reference-note">${esc(i.spec.glove_type)} · ${esc(i.spec.size)}</span>`:''}</div><div>${failing.length?status('fail'):missing.length?status('hold'):status(i.evaluation.sections.measurements)}</div></div>${missing.length&&i.spec?`<div class="notice">${icon('info-circle')}<div><strong>Some measurement limits are not available</strong>${esc(missing.map(m=>m.label).join(', '))} will be recorded for review.</div></div>`:''}<div class="measurement-grid-wrap"><table class="measurement-grid" aria-label="Measurement readings by sample"><thead><tr><th class="sticky-sample">Sample</th>${metrics.map(m=>`<th><span>${esc(m.label)}</span><small>${esc(measurementLimitSummary(i,m))}</small></th>`).join('')}</tr></thead><tbody>${Array.from({length:maxSamples},(_,n)=>`<tr><th class="sticky-sample numeric">${String(n+1).padStart(2,'0')}</th>${metrics.map(m=>measurementCell(i,m,n)).join('')}</tr>`).join('')}</tbody></table></div><div class="measurement-stats-grid">${metrics.map(m=>`<div><strong>${esc(m.label)}</strong><div id="reading-stats-${m.key}" class="reading-stats compact">${readingStats(i.data.measurements[m.key]||[])}</div></div>`).join('')}</div>`,status(i.evaluation.sections.measurements));};
reviewView=function(i){const e=i.evaluation;const refs=S.meta.products[i.product].references;return surface('Review inspection','Resolve incomplete entries and inspect exceptions before submission.',`<div class="review-summary">${icon(e.result==='fail'?'clipboard-x':e.can_submit?'clipboard-check':'clipboard-list')}<div><h2>${e.can_submit?'Ready for supervisor review':e.missing.length+' items need completion'}</h2><p>${esc(i.unit_label)} · ${esc(i.glove_type)} · Size ${esc(sizeLabel(i))}</p></div>${status(e.result)}</div><div class="field-grid two review-submit-fields">${select('inspector_id','Inspector ID *',refs['Inspector ID'],i.data.fields.inspector_id)}${input('verify_id','Verify ID',i.data.fields.verify_id,'text','maxlength="80"')}</div><div class="review-columns"><div><h3>Activity results</h3>${Object.entries(e.sections).map(([k,v])=>`<div class="review-row"><button class="btn ghost small" data-action="section" data-section="${k}">${sections[k]} ${icon('arrow-up-right')}</button>${status(v)}</div>`).join('')}<div class="info-band">${icon('user-check')}<span>Submission locks this record. Verification is completed by a different supervisor.</span></div></div><div><h3>${e.issues.length?'Exceptions ('+e.issues.length+')':'No failed checks'}</h3>${e.issues.map(issue=>issueLink(issue,true)).join('')}${e.missing.length?`<h3 style="margin-top:22px">To complete</h3>${e.missing.map(issue=>issueLink(issue)).join('')}`:'<p class="muted" style="margin-top:12px;font-size:12px">All required readings and traceability fields are recorded.</p>'}</div></div>`,status(e.result));};
localEvaluateInspection=function(i){const definition=S.meta.products[i.product],data=i.data,limits=i.spec?.limits||{},checks={},issues=[],missing=[],categories=['Critical','Holes','Major','Minor','Packaging'];for(const [key,label] of Object.entries({batch_no:'Batch number',pallet_no:'Pallet number',inspection_date:'Inspection date',inspection_status:'Inspection status',sample_size:'Sample size',sample_qty:'Sample quantity',cartons_per_pallet:'Cartons per pallet'}))if(String(data.fields?.[key]??'').trim()==='')missing.push({section:'information',key,message:`Enter ${label}.`});if(String(data.fields?.inspector_id??'').trim()==='')missing.push({section:'review',key:'inspector_id',message:'Enter Inspector ID.'});for(const metric of definition.metrics){const key=metric.key,limit=limits[key]||{},values=data.measurements?.[key]||[],results=[];if(limit.na){checks[key]={label:metric.label,section:metric.section,result:'na',entered:0,expected:0,readings:[]};continue;}for(let n=0;n<metric.samples;n++){const v=values[n]??null,r=readingResult(v,limit);results.push(r);if(r==='fail')issues.push({section:metric.section,key,sample:n+1,message:`${metric.label} sample ${n+1}: ${v} ${metric.unit}; required ${localSpecRange(limit,metric.unit)}.`});}const entered=values.filter(v=>v!==null&&v!==''&&v!==undefined).length;const assessed=results.filter(r=>r!=='pending');let result=localAggregate(assessed);if(key==='thickness'&&i.product==='hdpe'&&(limit.min??null)===null&&(limit.max??null)===null&&entered>0)result='na';if(key==='air_pump'&&i.product==='cpetpe'&&(limit.min??null)===null&&(limit.max??null)===null&&entered>0)result='pass';if(result==='unassessed'&&entered>0)issues.push({section:metric.section,key,message:`${metric.label}: specification not available; requires review.`});checks[key]={label:metric.label,section:metric.section,result,entered,expected:metric.samples,readings:results};}for(const test of definition.tests){const key=test.key,values=data.tests?.[key]||[],results=[];for(let n=0;n<test.samples;n++)results.push(String(values[n]||'na').toLowerCase());const assessed=results.filter(r=>r!=='pending');const result=localAggregate(assessed);checks[key]={label:test.label,section:'tests',result,readings:results};if(result==='fail'){issues.push({section:'tests',key,message:`${test.label}: ${test.failure||data.fields?.[key+'_defect']||'Failed test'}.`});if(test.defects&&!data.fields?.[key+'_defect'])missing.push({section:'tests',key,message:`Select the ${test.label} defect.`});}}for(const category of categories){const total=(data.defects||[]).filter(d=>d.category===category).reduce((n,d)=>n+Number(d.quantity||0),0),result=total>0?'fail':'pass';checks['defect_'+category]={label:category,section:'defects',result,total};if(result==='fail')issues.push({section:'defects',key:category,message:`${category}: ${total} defect(s). Zero-tolerance acceptance exceeded.`});}for(const [key,label] of Object.entries({pcs:'Pieces',inner:'Inner',polybag:'Polybag'})){const value=data.fields?.['count_'+key]??'',disposition=data.fields?.['count_'+key+'_result']??'',result=disposition===''?'pending':disposition==='PASS'?'pass':'fail';checks['count_'+key]={label:label+' count',section:'packing',result};if(value===''||disposition==='')missing.push({section:'packing',key:'count_'+key,message:`Complete ${label} count and disposition.`});if(result==='fail')issues.push({section:'packing',key:'count_'+key,message:`${label} count: ${disposition}.`});}for(const [key,label] of Object.entries({scale_id:'Weighing scale ID',ruler_id:'Ruler ID',gauge_id:'Thickness gauge ID',packer_id:'Packer ID'}))if(!data.fields?.[key])missing.push({section:'packing',key,message:`Enter ${label}.`});for(const key of ['length_a','glove_length','gap_length'])if(checks[key]?.result==='fail'&&!data.fields?.[key+'_defect'])missing.push({section:'measurements',key,message:`Select the ${checks[key].label} defect.`});const sectionStates={};for(const section of ['information','defects','tests','measurements','packing']){const states=Object.values(checks).filter(c=>c.section===section).map(c=>c.result);if(missing.some(m=>m.section===section))states.push('pending');sectionStates[section]=localAggregate(states.length?states:['pass']);}let result=localAggregate(Object.values(sectionStates));if(result==='unassessed')result='hold';return{result,checks,sections:sectionStates,issues,missing,can_submit:missing.length===0,passed:Object.values(checks).filter(c=>c.result==='pass').length,failed:Object.values(checks).filter(c=>c.result==='fail').length};};

informationView=function(i){const f=i.data.fields,refs=S.meta.products[i.product].references;return surface('Confirm this inspection unit','Order details are shared. Sampling, batch and unit identity belong to this inspection.',`<div class="subheading"><h3>Order context</h3></div><dl class="key-values" style="grid-template-columns:repeat(3,minmax(0,1fr));margin:0">${Object.entries({Factory:i.common.factory,Plant:i.common.plant,'Item number':i.common.item_no,'Lot number':i.common.lot_no,Customer:i.common.customer,Country:i.common.country,Brand:i.common.brand,'Product type':i.common.product_type,Colour:i.common.colour}).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'Not recorded')}</dd></div>`).join('')}</dl><div class="divider"></div><div class="subheading"><h3>Unit identity & sampling</h3><p>Fields marked * are needed before submission.</p></div><div class="field-grid">${input('batch_no','Batch number *',f.batch_no)}${input('pallet_no','Pallet number *',f.pallet_no,'text','readonly')}${input('carton_no','Carton number',f.carton_no)}${select('glove_type_code','Glove Type / Code',refs['Glove Type'],f.glove_type_code||i.glove_type)}${input('inspection_date','Inspection date *',f.inspection_date,'date')}${select('inspection_status','Inspection status *',refs['Inspection Status'],f.inspection_status)}${refs.Embossment?select('embossment','Embossment',refs.Embossment,f.embossment):input('embossment','Embossment',f.embossment)}${select('machine_no',i.product==='hdpe'?'HD number':'STM number',refs[i.product==='hdpe'?'HD No.':'STM No.'],f.machine_no)}${input('stamping_date','Stamping date',f.stamping_date,'date')}${input('sample_size','Sample size (pcs) *',f.sample_size,'number','min="1" step="1"','Enter the approved sampling quantity.')}${input('sample_qty','Sample quantity (cartons x pcs) *',f.sample_qty,'text','placeholder="e.g. 2 cartons x 100 pcs"')}${input('cartons_per_pallet','Carton per pallet *',f.cartons_per_pallet,'number','min="0" step="1"')}</div>`,status(i.evaluation.sections.information));};
